import { useSyncExternalStore } from 'react';

// The date this user's screen is shown as of (yyyy-mm-dd), '' when it shows the sheet as it is now. It
// belongs to this screen only: every request names it (X-As-Of, see http.ts), so the server answers a read
// as the store stood at the end of that date and refuses every change while it is set.
let asOf = '';
const listeners = new Set<() => void>();

function subscribe(listener: () => void) {
  listeners.add(listener);
  return () => {
    listeners.delete(listener);
  };
}

/** The as-of date the requests name now ('' for none). */
export function currentAsOf(): string {
  return asOf;
}

export function setAsOf(date: string): void {
  if (asOf === date) return;
  asOf = date;
  listeners.forEach((l) => l());
}

/** The as-of date shown on this screen ('' for none). */
export function useAsOf(): string {
  return useSyncExternalStore(subscribe, () => asOf);
}
import { useState } from 'react';
import type { FormEvent } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import { setAsOf, useAsOf } from '../../api/asOf';
import { SheetPanel } from '../../slots/defs/sheetPanel';

const DATE = /^\d{4}-\d{2}-\d{2}$/;

/** Whether the text is a real date (yyyy-mm-dd). */
function isDate(text: string): boolean {
  if (!DATE.test(text)) return false;
  const d = new Date(`${text}T00:00:00Z`);
  return !Number.isNaN(d.getTime()) && d.toISOString().slice(0, 10) === text;
}

/**
 * Shows the sheet as of a date, on this user's screen only: every figure, flag, list and line as it stood at the
 * end of that date, the date standing in for the sheet's today. While it is set every change is refused (by the
 * server, with the usual error of the form or action). Clearing it shows the sheet as it is now.
 */
function AsOfView() {
  const asOf = useAsOf();
  const queryClient = useQueryClient();
  const [typed, setTyped] = useState('');
  const [error, setError] = useState('');

  // Every query kept per sheet is read afresh for the new date; none shows what it read for another.
  const show = (date: string) => {
    setAsOf(date);
    void queryClient.resetQueries({ queryKey: ['sheet'] });
  };

  const submit = (e: FormEvent) => {
    e.preventDefault();
    const date = typed.trim();
    if (!isDate(date)) {
      setError('The as-of date must be a date (yyyy-mm-dd).');
      return;
    }
    setError('');
    show(date);
  };

  return (
    <form data-testid="asof-form" onSubmit={submit}>
      As of <strong data-testid="sheet-asof">{asOf}</strong>{' '}
      <input
        data-testid="asof-date"
        placeholder="yyyy-mm-dd"
        value={typed}
        onChange={(e) => {
          setTyped(e.target.value);
          setError('');
        }}
      />{' '}
      <button type="submit" data-testid="asof-set">
        Show as of
      </button>{' '}
      <button
        type="button"
        data-testid="asof-clear"
        onClick={() => {
          setError('');
          setTyped('');
          show('');
        }}
      >
        Show now
      </button>
      {error && <p data-testid="asof-error">{error}</p>}
    </form>
  );
}

export const contribution = SheetPanel.fill({ order: 0.5, Component: AsOfView });
import { useQuery } from '@tanstack/react-query';
import { downloadCsv } from '../../api/csv';
import { SheetPanel } from '../../slots/defs/sheetPanel';
import { claimsQuery } from '../claims/claimsQuery';
import { personDue, ratesQuery } from '../rates/ratesQuery';
import { useCap, useFloor, useLate } from '../settings/settingsQuery';
import { useSheetToday } from '../sheet/useSheetToday';
import { gradeOn, peopleQuery } from './peopleQuery';

/** Downloads the people as CSV, in list order and retired people included, with the figures the screen shows. */
function ExportPeople({ sheetId }: { sheetId: string }) {
  const people = useQuery(peopleQuery(sheetId)).data ?? [];
  const claims = useQuery(claimsQuery(sheetId)).data ?? [];
  const rates = useQuery(ratesQuery(sheetId)).data ?? [];
  const today = useSheetToday(sheetId);
  const floor = useFloor(sheetId);
  const late = useLate(sheetId);
  const cap = useCap(sheetId);

  const exportCsv = () => {
    downloadCsv('people.csv', [
      ['name', 'grade', 'retired-from', 'due-total'],
      ...people.map((p) => [p.name, gradeOn(p, today) ?? p.grade, p.retiredFrom ?? '', personDue(p, people, claims, rates, today, floor, late, cap)]),
    ]);
  };

  return (
    <p>
      <button type="button" data-testid="export-people" onClick={exportCsv}>
        Export people (CSV)
      </button>
    </p>
  );
}

export const contribution = SheetPanel.fill({ order: 11, Component: ExportPeople });
import { useQuery } from '@tanstack/react-query';
import { downloadCsv } from '../../api/csv';
import { SheetPanel } from '../../slots/defs/sheetPanel';
import { peopleQuery } from '../people/peopleQuery';
import { periodOf, periodsQuery } from '../periods/periodsQuery';
import { figure, ratesQuery } from '../rates/ratesQuery';
import { useFloor, useLate } from '../settings/settingsQuery';
import { claimsQuery } from './claimsQuery';

/**
 * Downloads the claims as CSV: people in list order (retired people included, shown or not), each person's claims
 * oldest first, with the figures the screen shows (an empty number or period, and n/a, as they are).
 */
function ExportClaims({ sheetId }: { sheetId: string }) {
  const people = useQuery(peopleQuery(sheetId)).data ?? [];
  const claims = useQuery(claimsQuery(sheetId)).data ?? [];
  const rates = useQuery(ratesQuery(sheetId)).data ?? [];
  const periods = useQuery(periodsQuery(sheetId)).data ?? [];
  const floor = useFloor(sheetId);
  const late = useLate(sheetId);

  const exportCsv = () => {
    downloadCsv('claims.csv', [
      ['person', 'number', 'date', 'amount', 'due', 'status', 'period'],
      ...people.flatMap((p) =>
        claims
          .filter((c) => c.personId === p.id)
          .reverse()
          .map((c) => [
            p.name,
            c.number ?? '',
            c.date,
            c.amount,
            figure(c, rates, p, floor, late),
            c.status,
            periodOf(periods, c.dueBy)?.name ?? '',
          ]),
      ),
    ]);
  };

  return (
    <p>
      <button type="button" data-testid="export-claims" onClick={exportCsv}>
        Export claims (CSV)
      </button>
    </p>
  );
}

export const contribution = SheetPanel.fill({ order: 11.5, Component: ExportClaims });
import { useQueryClient } from '@tanstack/react-query';
import { downloadCsv } from '../../api/csv';
import { SheetPanel } from '../../slots/defs/sheetPanel';
import { poolsQuery } from './poolsQuery';

/** Downloads the pools as CSV: one line per member, pools and members in the order added, a pool member as pool:<name>
 *  and the cut as shown (empty when none). The pools are re-read first, so the file holds what the store holds now. */
function ExportPools({ sheetId }: { sheetId: string }) {
  const queryClient = useQueryClient();

  const exportCsv = async () => {
    const pools = await queryClient.fetchQuery({ ...poolsQuery(sheetId), staleTime: 0 });
    downloadCsv('pools.csv', [
      ['pool', 'member', 'share', 'cut'],
      ...pools.flatMap((p) => p.members.map((m) => [p.name, m.pool === null ? m.name : `pool:${m.pool}`, m.share, m.cut])),
    ]);
  };

  return (
    <p>
      <button type="button" data-testid="export-pools" onClick={() => void exportCsv()}>
        Export pools (CSV)
      </button>
    </p>
  );
}

export const contribution = SheetPanel.fill({ order: 6.81, Component: ExportPools });
/** A CSV value: wrapped in double quotes, with inner quotes doubled, when it holds a comma, a quote or a line break. */
export function csvValue(value: string): string {
  return /[",\r\n]/.test(value) ? `"${value.replace(/"/g, '""')}"` : value;
}

/** Downloads the rows (each a list of values) as a CSV file, every line ending in "\n". */
export function downloadCsv(fileName: string, rows: string[][]): void {
  const text = rows.map((r) => r.map(csvValue).join(',') + '\n').join('');
  const url = URL.createObjectURL(new Blob([text], { type: 'text/csv' }));
  const a = document.createElement('a');
  a.href = url;
  a.download = fileName;
  a.click();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}
