      ...pools.flatMap((p) => p.members.map((m) => [p.name, m.pool === null ? m.name : `pool:${m.pool}`, m.share, m.cut])),
    ]);
  };

  return (
    <p>
      <button type="button" data-testid="export-pools" onClick={() => void exportCsv()}>
        Export pools (CSV)
      </button>
    </p>
  );
}

